children.css:
.ai-image-gallery-aakv6zgi2athlcwhqbaigenblockf4be74efgi87e {
  width: 100%;
  padding: 40px 0;
}

.ai-image-gallery__container-aakv6zgi2athlcwhqbaigenblockf4be74efgi87e {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}

.ai-image-gallery__grid-aakv6zgi2athlcwhqbaigenblockf4be74efgi87e {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin-top: 24px;
}

.ai-image-gallery__title-aakv6zgi2athlcwhqbaigenblockf4be74efgi87e {
  text-align: center;
  color: #000000;
  font-size: 32px;
  margin: 0;
}

.ai-image-gallery__item-aakv6zgi2athlcwhqbaigenblockf4be74efgi87e {
  position: relative;
  overflow: hidden;
  border-radius: 8px;
  background-color: #f4f4f4;
  aspect-ratio: 16/9;
}

.ai-image-gallery__image-aakv6zgi2athlcwhqbaigenblockf4be74efgi87e {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s ease;
}

.ai-image-gallery__placeholder-aakv6zgi2athlcwhqbaigenblockf4be74efgi87e {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #f4f4f4;
  position: relative;
}

.ai-image-gallery__placeholder-aakv6zgi2athlcwhqbaigenblockf4be74efgi87e svg {
  width: 60%;
  height: 60%;
  opacity: 0.3;
}

.ai-image-gallery__empty-state-aakv6zgi2athlcwhqbaigenblockf4be74efgi87e {
  position: absolute;
  bottom: 10px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 12px;
  color: #666;
  text-align: center;
  pointer-events: none;
}


  .ai-image-gallery__item-aakv6zgi2athlcwhqbaigenblockf4be74efgi87e:hover .ai-image-gallery__image-aakv6zgi2athlcwhqbaigenblockf4be74efgi87e {
    transform: scale(1.05);
  }


.ai-image-gallery__overlay-aakv6zgi2athlcwhqbaigenblockf4be74efgi87e {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(
    to bottom,
    rgba(0, 0, 0, 0) 0%,
    rgba(0, 0, 0, 0.4) 100%
  );
  opacity: 0;
  transition: opacity 0.3s ease;
  display: flex;
  align-items: flex-end;
  padding: 20px;
}


  .ai-image-gallery__item-aakv6zgi2athlcwhqbaigenblockf4be74efgi87e:hover .ai-image-gallery__overlay-aakv6zgi2athlcwhqbaigenblockf4be74efgi87e {
    opacity: 1;
  }


.ai-image-gallery__caption-aakv6zgi2athlcwhqbaigenblockf4be74efgi87e {
  color: white;
  font-size: 14px;
  font-weight: 500;
}

@media screen and (max-width: 768px) {
  .ai-image-gallery__grid-aakv6zgi2athlcwhqbaigenblockf4be74efgi87e {
    grid-template-columns: repeat(2, 1fr);
    gap: 12.0px;
  }

  .ai-image-gallery__container-aakv6zgi2athlcwhqbaigenblockf4be74efgi87e {
    padding: 0 15px;
  }
}

@media screen and (max-width: 480px) {
  .ai-image-gallery__grid-aakv6zgi2athlcwhqbaigenblockf4be74efgi87e {
    grid-template-columns: repeat(1, 1fr);
    gap: 8.0px;
  }

  .ai-image-gallery__title-aakv6zgi2athlcwhqbaigenblockf4be74efgi87e {
    font-size: 25.6px;
  }

  .ai-image-gallery__container-aakv6zgi2athlcwhqbaigenblockf4be74efgi87e {
    padding: 0 10px;
  }
}

